import{_ as t,o as e,c as r,a2 as s}from"./chunks/framework.B2QVIpOM.js";const h=JSON.parse('{"title":"协恩中学 · 2022/23资料年份 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-fd1436e9","school_zh":"协恩中学","school_en":"—","grade":"s1","year":"2022-23","year_label":"2022/23资料年份","type":"interview","title":"协恩中学 · 2022/23资料年份 · 中一 · 面试","anonymous":true,"source_ids":["C2223-HYS"],"rounds":["r1","r2"]},"headers":[],"relativePath":"reports/school-fd1436e9/s1/2022-23-interview.md","filePath":"reports/school-fd1436e9/s1/2022-23-interview.md"}'),p={name:"reports/school-fd1436e9/s1/2022-23-interview.md"};function n(a,o,c,l,g,i){return e(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="协恩中学-·-2022-23资料年份-·-中一-·-面试" tabindex="-1">协恩中学 · 2022/23资料年份 · 中一 · 面试 <a class="header-anchor" href="#协恩中学-·-2022-23资料年份-·-中一-·-面试" aria-label="Permalink to &quot;协恩中学 · 2022/23资料年份 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-fd1436e9">← 返回协恩中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c2223-hys" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-hys" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-hys}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>首轮分科口头评估</strong></p><p>多份反馈以中文、英语及数学短时任务为主。中文阅读准备时间由1至3分钟不等，英文常见一分钟阅读、一分钟朗读或答题；数学约2至2.5分钟完成20题，可跳题。各人的记忆略有差异。</p></blockquote><blockquote><p><strong>语文：</strong> 中文，口语未注明</p><p><strong>诗文与语言题</strong></p><p>材料包括诗歌、景物描写、亲情友情爱情等。朗读后考内容短答、第三段大意、改错、选字选词填空及解释引用作结的作用；有记录为两篇各7至8行、共5题，也有记为每篇3至4题或一分钟答9题。</p><p><strong>具体理解与观点</strong></p><p>题目涉及如何种植杜鹃、亲情友情爱情中哪种最重要，以及“可以戴面具，但不要遮住真实自己”的寓意。另有《伞》及“绿色的魔术……”开头文章的回忆，后者包含错字辨认和文中词语解释，完整文字未可靠保留。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>边读边填词</strong></p><p>朗读时补上文中空格，有的给单词首字母，有的不给词。考生记得鹦鹉认知相关文章及一篇日记找学校的文章；也有“No pain ___ ___”配词。部分学生反馈生词很多。</p><p><strong>比较活动与表达偏好</strong></p><p>根据巴士与地铁、博物馆与平板、烹饪与功夫等图片，说明人们为何选择这些活动或方式，并表达自己的偏好及理由。另问为何网上查历史资料而不到博物馆，以及用一分钟谈YouTube。</p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>速算与图形</strong></p><p>约20题，涉及分数运算及通分、小数、三位数计算、百分率、平均数、方程和图中三角形数量。具体回忆有12与8的最大公因数、43−6×7。</p><p><strong>未完整的题目回忆</strong></p><p>另记有含“3x−8”求x及“600＋20%＋50%”的题，等式条件及百分率基数不完整，不能还原为唯一计算题。有考生完成约14题，也有考生称没有奥数题。</p></blockquote><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>学生面试：</strong> 英语及粤语</p><p><strong>一分钟介绍与持续追问</strong></p><p>第二轮见校长及资深老师，家长一同进入；桌上有计时器。先作一分钟英语自我介绍，再按介绍及奖项追问，有考生反馈英语交流约10分钟。</p><p><strong>经历与适应</strong></p><p>最深刻的奖项及原因、协恩学生有什么特质、说父亲幽默能否举例、与同学关系如何、运动经历、最喜欢与不喜欢的科目、能否应付中学增加的科目。</p><p><strong>择校、挫折与反问</strong></p><p>为什么选择协恩、学校哪里吸引自己、还报了哪些学校、觉得自己像哪所学校的毕业生、有没有差一点成功却遗憾落败的经历。老师亦询问家长是否认同接受挫折的教育理念，最后让学生和家长提问。</p></blockquote><blockquote><p><strong>学生与家长反馈：</strong></p><p><strong>学生提问示例</strong></p><p>一位学生询问学校活动及比赛很多，如何仍能支援学生保持学业表现；家长感到校长会根据回答连续追问。</p></blockquote>',15)])])}const _=t(p,[["render",n]]);export{h as __pageData,_ as default};
